// ============================================
// VALIDATION INPUT - MCP DOCX Extractor
// RFC-014 extraction with optional context fields
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- OPTIONAL context fields (extract for tracing, NO validation errors) ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- Required parameters specific to this webhook ---
const fileUrl = body.file_url || ctx.file_url;
const fileBase64 = body.file_base64 || ctx.file_base64;

if (!fileUrl && !fileBase64) {
  errors.push('file_url or file_base64 required');
}

// --- Optional parameters ---
const outputFormat = body.output_format || ctx.output_format || 'text';
const includeMetadata = body.include_metadata || ctx.include_metadata || false;
const includeImages = body.include_images || ctx.include_images || false;
const openaiApiKey = body.openai_api_key || ctx.openai_api_key || null;
const useVision = body.use_vision || ctx.use_vision || false;

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

return {
  valid: true,
  file_url: fileUrl,
  file_base64: fileBase64,
  output_format: outputFormat,
  include_metadata: includeMetadata,
  include_images: includeImages,
  openai_api_key: openaiApiKey,
  use_vision: useVision,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'docx-extractor',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

// ============================================
// EXTRACT DOCX CONTENT - MCP DOCX Extractor
// ============================================

const prevData = $('Validate Input').first().json;
const outputFormat = prevData.output_format;

try {
  let fileContent;

  if (prevData.file_base64) {
    fileContent = prevData.file_base64;
  } else {
    // File was downloaded
    const items = $input.all();
    if (items[0]?.json?.error) {
      return [{
        json: {
          success: false,
          _trace: {
            service_response: { download_error: items[0].json.error.message || 'Unknown error' },
            provider: 'docx-extractor',
            mode: 'error',
            latency_ms: Date.now() - prevData.startTime,
            user_id: prevData.user_id,
            guild_id: prevData.guild_id,
            user_request: prevData.user_request
          },
          error: {
            code: 'DOWNLOAD_ERROR',
            message: 'Failed to download file: ' + (items[0].json.error.message || 'Unknown error'),
            http_status: 500
          },
          user_id: prevData.user_id,
          guild_id: prevData.guild_id,
          user_request: prevData.user_request
        }
      }];
    }
    fileContent = items[0]?.binary?.data?.data || '';
  }

  // DOCX is a ZIP file containing XML
  // Basic extraction approach - in production use mammoth.js
  // This is a placeholder that demonstrates the workflow structure

  const extractionResult = {
    content: 'DOCX extraction requires mammoth.js library. Please configure n8n with custom nodes for full DOCX support.',
    format: outputFormat,
    metadata: {
      file_type: 'docx',
      extraction_method: 'placeholder'
    },
    note: 'For production use, install mammoth npm package in n8n custom function node'
  };

  // If we have OpenAI key, use GPT-4 Vision for extraction from rendered preview
  if (prevData.openai_api_key && prevData.use_vision) {
    extractionResult.vision_extraction_available = true;
  }

  return [{
    json: {
      success: true,
      data: extractionResult,
      meta: {
        provider: 'docx-extractor',
        output_format: outputFormat
      },
      _trace: {
        service_response: extractionResult,
        provider: 'docx-extractor',
        mode: 'success',
        latency_ms: Date.now() - prevData.startTime,
        user_id: prevData.user_id,
        guild_id: prevData.guild_id,
        user_request: prevData.user_request
      },
      user_id: prevData.user_id,
      guild_id: prevData.guild_id,
      user_request: prevData.user_request
    }
  }];

} catch (e) {
  return [{
    json: {
      success: false,
      _trace: {
        service_response: { extraction_error: e.message },
        provider: 'docx-extractor',
        mode: 'error',
        latency_ms: Date.now() - prevData.startTime,
        user_id: prevData.user_id,
        guild_id: prevData.guild_id,
        user_request: prevData.user_request
      },
      error: {
        code: 'EXTRACTION_ERROR',
        message: 'Failed to extract DOCX: ' + e.message,
        http_status: 500
      },
      user_id: prevData.user_id,
      guild_id: prevData.guild_id,
      user_request: prevData.user_request
    }
  }];
}

